fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    for j in 0..sub.len() {
        if main[start + j] != sub[j] {
            return false;
        }
    }
    true
}

fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    if sub.is_empty() {
        return true; // An empty subarray is always a subarray
    }
    
    let main_len = main.len();
    let sub_len = sub.len();
    
    if sub_len > main_len {
        return false; // The subarray is longer than the main array
    }
    
    for i in 0..=main_len - sub_len {
        if check_match_at(main, sub, i) {
            return true; // Found a match
        }
    }
    
    false // No match found
}